validator:
function validate(input) {
  const [{ Coordinates = [] }] = input;
  for (const [x, y] of Coordinates) if (x === null || y === null) return 'X and Y cannot be null.';
  return null;
}

generator:
function generate(rand, size) {
  const count = size === 'small' ? Math.floor(rand() * 9) : 1500 + Math.floor(rand() * 500);
  const low = size === 'small' ? 1 : -40, span = size === 'small' ? 4 : 120;
  const value = () => low + Math.floor(rand() * span);
  const Coordinates = [];
  for (let i = 0; i < count; i++) {
    const roll = rand();
    if (roll < 0.25 && Coordinates.length) {
      // Mirror an earlier row, which may also repeat a diagonal point.
      const [x, y] = Coordinates[Math.floor(rand() * Coordinates.length)];
      Coordinates.push([y, x]);
    } else if (roll < 0.35) {
      const v = value();
      Coordinates.push([v, v]);
    } else {
      Coordinates.push([value(), value()]);
    }
  }
  return [{ Coordinates }];
}
